{"cells":[{"cell_type":"code","source":"from fastapi import APIRouter, Depends, HTTPException, Query\nfrom typing import Optional\nfrom . import database, openai_client, auth\n\nrouter = APIRouter()\n\n@router.get(\"/api/ask\")\nasync def ask_question(\n    query: str,\n    user_id: str,\n    file_url: Optional[str] = None,\n    user: dict = Depends(auth.get_current_user)\n):\n    try:\n        response_content = await openai_client.generate_response(query, file_url)\n        await database.add_conversation_turn(user_id, \"user\", query)\n        await database.add_conversation_turn(user_id, \"assistant\", response_content)\n        return {\"response\": response_content}\n    except Exception as e:\n        raise HTTPException(status_code=500, detail=str(e))\n\n\n@router.post(\"/api/logout\")\nasync def clear_chat_history(\n    user_id: str,\n    user: dict = Depends(auth.get_current_user)\n):\n    try:\n        await database.delete_user_history(user_id)\n        return {\"message\": \"Chat history cleared successfully.\"}\n    except Exception as e:\n        raise HTTPException(status_code=500, detail=str(e))\n\n@router.get(\"/api/speech\")\nasync def get_speech_config():\n    return {\n        \"token\": \"your_speech_service_token\",\n        \"region\": \"your_speech_service_region\",\n        \"languages\": [\"en-US\", \"fr-FR\", \"de-DE\", \"it-IT\"]\n    }","outputs":[],"execution_count":null,"metadata":{}}],"metadata":{"colab":{"from_bard":true},"kernelspec":{"display_name":"Python 3","name":"python3"}},"nbformat":4,"nbformat_minor":0}